2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioOutput {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	
58	const BASE_PREMIUMS: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	/**
68	 * What each item is insured FOR — distinct from its base premium above.
69	 * A block of 3 alike components discounts the premium only, never this sum.
70	 */
71	const INSURANCE_VALUES: Record<string, number> = {
72	  sword: 1000,
73	  amulet: 600,
74	  staff: 800,
75	  potion: 400,
76	  rune: 250,
77	  moonstone: 250,
78	};
79	
80	const DEDUCTIBLE_PER_DAMAGE = 100;
81	const CAP_MULTIPLIER = 2;
82	
83	/** Premiums round up — the MHPCO's favour. */
84	const roundPremium = (amount: number): number => Math.ceil(amount);
85	
86	const policyCap = (items: Item[]): number =>
87	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0) *
88	  CAP_MULTIPLIER;
89	
90	/**
91	 * Damage to a very highly enchanted item is only half reimbursed. NOTE this
92	 * threshold (8) is NOT the quote-side `HIGH_ENCHANTMENT_THRESHOLD` (5) — two
93	 * distinct rules that both key off enchantment.
94	 */
95	const HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD = 8;
96	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
97	
98	/** The share of a damage amount the MHPCO reimburses, before the deductible. */
99	const reimbursementRate = (item: Item | undefined): number =>
100	  (item?.enchantment ?? 0) >= HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD
101	    ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
102	    : 1;
103	
104	const claimPayout = (
105	  incident: Incident,
106	  insuredItems: Item[],
107	  remainingCap: number,
108	): number => {
109	  // Reimburse first, deduct second: a 1000 G damage at 50 % is 500 − 100 = 400,
110	  // not (1000 − 100) / 2 = 450.
111	  const reimbursed = incident.damages.reduce((sum, damage) => {
112	    const item = insuredItems.find((candidate) => candidate.type === damage.itemType);
113	    return (
114	      sum + damage.amount * reimbursementRate(item) - DEDUCTIBLE_PER_DAMAGE
115	    );
116	  }, 0);
117	  return Math.min(reimbursed, remainingCap);
118	};
119	
120	const BLOCK_SIZE = 3;
121	const BLOCK_BASE_PREMIUM = 60;
122	
123	const countByType = (items: Item[]): Map<string, number> => {
124	  const counts = new Map<string, number>();
125	  for (const item of items) {
126	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
127	  }
128	  return counts;
129	};
130	
131	/** A group of exactly 3 alike components is priced as one building block. */
132	const groupBasePremium = (type: string, count: number): number =>
133	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
134	
135	const LOYALTY_DISCOUNT_RATE = 0.2;
136	const LOYALTY_YEARS_THRESHOLD = 2;
137	const FOLLOWUP_DISCOUNT_RATE = 0.15;
138	
139	const CURSE_SURCHARGE_RATE = 0.5;
140	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
141	const HIGH_ENCHANTMENT_THRESHOLD = 5;
142	
143	/**
144	 * Rates are SUMMED here and multiplied by the base premium once by the caller,
145	 * so two modifiers on one item are additive (0.5 + 0.3) rather than
146	 * compounding (× 1.5 × 1.3) — per the spec's integration example.
147	 */
148	const itemSurchargeRate = (item: Item): number => {
149	  const curseRate = item.cursed ? CURSE_SURCHARGE_RATE : 0;
150	  const highEnchantmentRate =
151	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
152	      ? HIGH_ENCHANTMENT_SURCHARGE_RATE
153	      : 0;
154	  return curseRate + highEnchantmentRate;
155	};
156	
157	/**
158	 * Item-specific surcharges apply to the affected item's OWN base premium, so
159	 * they need a per-item pass — the grouping in `countByType` collapses both
160	 * `cursed` and `enchantment`.
161	 */
162	const itemSurcharges = (items: Item[]): number =>
163	  items.reduce(
164	    (sum, item) => sum + BASE_PREMIUMS[item.type] * itemSurchargeRate(item),
165	    0,
166	  );
167	
168	/** Is this contract a follow-up, i.e. not the customer's first in the run? */
169	const isFollowUpContract = (stepIndex: number): boolean => stepIndex > 0;
170	
171	const quotePremium = (
172	  step: QuoteStep,
173	  customer: Customer,
174	  stepIndex: number,
175	): number => {
176	  // Policy-scoped modifiers below are percentages of THIS total, never of a
177	  // running total — hence the explicit `policy` in the name: item surcharges
178	  // are percentages of each item's OWN base premium instead.
179	  const policyBasePremium = [...countByType(step.items)].reduce(
180	    (sum, [type, count]) => sum + groupBasePremium(type, count),
181	    0,
182	  );
183	
184	  /**
185	   * A conditional policy-scoped modifier: a rate on the policy base premium,
186	   * applied only when it is due. The two users differ solely in rate and
187	   * predicate — and deliberately in their INPUT: loyalty reads the customer,
188	   * the follow-up discount reads the step's position. That difference in input
189	   * is why the terms stay separate in the sum below rather than collapsing
190	   * into one lumped "adjustments" subtotal.
191	   */
192	  const policyModifier = (rate: number, isDue: boolean): number =>
193	    isDue ? policyBasePremium * rate : 0;
194	
195	  // Unconditional — every item in a quote counts as a first insurance — so it
196	  // does not go through `policyModifier`, which exists to gate a rate.
197	  const firstInsuranceSurcharge =
198	    policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
199	  const loyaltyDiscount = policyModifier(
200	    LOYALTY_DISCOUNT_RATE,
201	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
202	  );
203	  const followUpDiscount = policyModifier(
204	    FOLLOWUP_DISCOUNT_RATE,
205	    isFollowUpContract(stepIndex),
206	  );
207	
208	  return (
209	    policyBasePremium +
210	    itemSurcharges(step.items) +
211	    firstInsuranceSurcharge -
212	    loyaltyDiscount -
213	    followUpDiscount +
214	    PROCESSING_FEE
215	  );
216	};
217	
218	/**
219	 * Settles one claim against its policy's remaining cap, DECREMENTING that cap
220	 * in `remainingCapsByPolicy` — successive claims on one policy must each see
221	 * the previous one's decrement, so this is deliberately not a pure function.
222	 */
223	/** A policy as it stands: what it covers, and how much cap it has left. */
224	interface PolicyState {
225	  items: Item[];
226	  remainingCap: number;
227	}
228	
229	const claimResult = (
230	  step: ClaimStep,
231	  policiesByStepIndex: Map<number, PolicyState>,
232	): ClaimResult => {
233	  // PLACEHOLDER, not intended behaviour: a claim naming a policy that no quote
234	  // step created currently reads as an empty policy with zero cap, so it pays
235	  // out 0. Such a claim must be REJECTED; the pending dangling-policy test owns
236	  // replacing this.
237	  const policy = policiesByStepIndex.get(step.policy) ?? {
238	    items: [],
239	    remainingCap: 0,
240	  };
241	  const payout = claimPayout(step.incident, policy.items, policy.remainingCap);
242	  const remainingCap = policy.remainingCap - payout;
243	  policiesByStepIndex.set(step.policy, { ...policy, remainingCap });
244	  return { payout, remainingCap };
245	};
246	
247	export const runScenario = (scenario: Scenario): ScenarioOutput => {
248	  // Claim steps reference a policy by the index of the quote step that created
249	  // it, and the remaining cap persists across claims — so the steps cannot be
250	  // processed independently of one another. That cross-step state is why this
251	  // stays an explicit loop: a fold would have to carry both the result list and
252	  // this ledger in one accumulator, hiding the sequencing rather than showing it.
253	  const policiesByStepIndex = new Map<number, PolicyState>();
254	  const results: StepResult[] = [];
255	
256	  scenario.steps.forEach((step, stepIndex) => {
257	    if (step.op === "quote") {
258	      policiesByStepIndex.set(stepIndex, {
259	        items: step.items,
260	        remainingCap: policyCap(step.items),
261	      });
262	      results.push({
263	        premium: roundPremium(quotePremium(step, scenario.customer, stepIndex)),
264	      });
265	    } else {
266	      results.push(claimResult(step, policiesByStepIndex));
267	    }
268	  });
269	
270	  return { results };
271	};
272

