 * Damage to a very highly enchanted item is only half reimbursed. NOTE this
 * threshold (8) is NOT the quote-side `HIGH_ENCHANTMENT_THRESHOLD` (5) — two
 * distinct rules that both key off enchantment.
 */
const HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD = 8;
const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;

